"""Centralized langfuse import handling.

All langfuse imports MUST go through this module. Direct imports of langfuse
are banned via ruff (see pyproject.toml banned-api configuration).

This provides:
- Graceful fallback when langfuse is not installed (optional dependency)
- No-op implementations for decorators like @observe
- Context manager that only executes block when langfuse is available
  *and* credentials are configured

Usage:
    from rasa.builder.telemetry.langfuse_integration.langfuse_compat import (
        observe, with_langfuse,
    )

    # For decorators (works whether langfuse is installed or not):
    @observe()
    def my_function(): ...

    # For conditional code that requires langfuse:
    with with_langfuse() as lf:
        if lf:  # Block only runs if langfuse is available and configured
            client = lf.get_client()
"""

import asyncio
import os
from contextlib import contextmanager
from functools import wraps
from types import ModuleType
from typing import Any, Callable, Generator, Optional, TypeVar

from rasa.tracing.constants import (
    LANGFUSE_ENV_VAR_PUBLIC_KEY,
    LANGFUSE_ENV_VAR_SECRET_KEY,
)
from rasa.utils.common import update_langfuse_log_level

F = TypeVar("F", bound=Callable[..., Any])


def _no_op_observe(*args: Any, **kwargs: Any) -> Callable[[F], F]:
    """No-op implementation of langfuse.observe decorator that preserves types."""

    def decorator(func: F) -> F:
        if asyncio.iscoroutinefunction(func):

            @wraps(func)
            async def async_wrapper(*f_args: Any, **f_kwargs: Any) -> Any:
                return await func(*f_args, **f_kwargs)

            return async_wrapper  # type: ignore[return-value]

        @wraps(func)
        def wrapper(*f_args: Any, **f_kwargs: Any) -> Any:
            return func(*f_args, **f_kwargs)

        return wrapper  # type: ignore[return-value]

    return decorator


try:
    import langfuse as _langfuse  # noqa: TID251

    _LANGFUSE_AVAILABLE = True
    langfuse: Any = _langfuse

    # ENG-3245: the `langfuse` package sets the "langfuse" logger to WARNING at
    # import time, resetting any suppression applied earlier during Rasa's logging
    # setup. Re-apply the configured level here — right after the import that
    # triggers the reset — so the SDK's unconfigured-client WARNING noise stays
    # silenced regardless of whether logging was configured before or after this
    # import. All langfuse imports funnel through this module, so this is the one
    # place the reset can occur.
    update_langfuse_log_level()
except ImportError:
    _LANGFUSE_AVAILABLE = False

    class _MockLangfuse:
        """Mock langfuse module when the real one isn't installed."""

        observe = staticmethod(_no_op_observe)

        def get_client(self) -> None:
            return None

    langfuse = _MockLangfuse()


def is_langfuse_configured() -> bool:
    """Return whether Langfuse credentials are set in the environment.

    Both public and secret keys must be non-empty. Matches what
    ``configure_langfuse()`` writes from endpoints and what operators set
    manually. Package installation alone is not enough — see
    :func:`is_langfuse_available`.
    """
    public_key = os.environ.get(LANGFUSE_ENV_VAR_PUBLIC_KEY, "").strip()
    secret_key = os.environ.get(LANGFUSE_ENV_VAR_SECRET_KEY, "").strip()
    return bool(public_key) and bool(secret_key)


@contextmanager
def with_langfuse() -> Generator[Optional[ModuleType], None, None]:
    """Yield the langfuse module when installed and credentials are configured.

    If langfuse is not installed or ``LANGFUSE_PUBLIC_KEY`` /
    ``LANGFUSE_SECRET_KEY`` are missing, yields None. The block still executes;
    the caller must check the yielded value.

    Usage:
        with with_langfuse() as lf:
            if lf:
                lf.get_client().update_current_trace(...)
    """
    if _LANGFUSE_AVAILABLE and is_langfuse_configured():
        yield _langfuse
    else:
        yield None


def is_langfuse_available() -> bool:
    """Check if the langfuse package is installed.

    Use this for decoration-time checks where context manager isn't suitable.
    Does not check credentials — see :func:`is_langfuse_configured`.
    """
    return _LANGFUSE_AVAILABLE


def require_langfuse() -> ModuleType:
    """Return the langfuse module or raise ImportError if not available.

    Use this in modules that absolutely require langfuse (e.g., evaluators).
    Does not require credentials to be configured.

    Raises:
        ImportError: If langfuse is not installed.
    """
    if not _LANGFUSE_AVAILABLE:
        raise ImportError(
            "langfuse is required for this functionality. "
            "Install it with: pip install rasa-pro[monitoring]"
        )
    return _langfuse


def observe(*args: Any, **kwargs: Any) -> Callable[[F], F]:
    """Observe decorator that no-ops unless Langfuse is installed and configured.

    Configuration is checked at **call time** so ``configure_langfuse()`` can
    set credentials after modules are imported and decorated.
    """

    def decorator(func: F) -> F:
        if not _LANGFUSE_AVAILABLE:
            return _no_op_observe(*args, **kwargs)(func)

        observed = langfuse.observe(*args, **kwargs)(func)

        if asyncio.iscoroutinefunction(func):

            @wraps(func)
            async def async_wrapper(*f_args: Any, **f_kwargs: Any) -> Any:
                if is_langfuse_configured():
                    return await observed(*f_args, **f_kwargs)
                return await func(*f_args, **f_kwargs)

            return async_wrapper  # type: ignore[return-value]

        @wraps(func)
        def wrapper(*f_args: Any, **f_kwargs: Any) -> Any:
            if is_langfuse_configured():
                return observed(*f_args, **f_kwargs)
            return func(*f_args, **f_kwargs)

        return wrapper  # type: ignore[return-value]

    return decorator
